let slices = 12;
let pattern;
let masked;
let density;

const MaskTypes = ['circle', 'square', 'triangle', 'text'];
let ix = 0;

function setup() {
  createCanvas(400, 400);
	frameRate(30);
  density = pixelDensity();
}

function createBG() {
  let g = createGraphics(width, height);
  g.noStroke();
  g.translate(width / 2, height / 2);

	slices = min(13, max(1, floor(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 13)))) * 2;
  const inc = TWO_PI / slices;
  // fill the screen
  const d = dist(0, 0, width, height);
  let c = 0;
	const clrs = ["yellow", "black"]; ["red", "yellow", "cyan", "purple"];
  for (let i = 0; i < TWO_PI + inc; i += inc) {
		g.fill(clrs[c % clrs.length]);
    g.arc(0, 0, d, d, i, i + inc);
    c++;
  }

  pattern = createImage(width * density, height * density);
  pattern.copy(g, 0, 0, width, height, 0, 0, width * density, height * density);

  updateMask();
}

function mouseClicked() {
  ix = (ix + 1) % MaskTypes.length;
  updateMask();
}

function updateMask() {
  let m = makeMask(MaskTypes[ix]);

  masked = createImage(width * density, height * density);
  masked.copy(pattern, 0, 0, width * density, height * density, 0, 0, width * density, height * density);
  masked.mask(m);
}

function makeMask(type) {
  var g = createGraphics(width, height);
  g.noStroke();
  g.fill(0);
  g.translate(width / 2, height / 2);

  switch (type) {
    case 'circle':
      g.circle(0, 0, width / 1.4);
      break;
    case 'square':
      g.rect(-width / 4, -height / 4, width / 2, height / 2);
      break;
    case 'triangle':
      g.triangle(-width / 4, height / 4, 0, -height / 4, width / 4, height / 4);
      break;
    case 'text':
      g.textAlign(CENTER, CENTER);
      g.textSize(96);
      g.text("Hello!", 0, 0);
      break;
  }

  let mask = createImage(width * density, height * density);
  mask.copy(g, 0, 0, width, height, 0, 0, width * density, height * density);

  return mask;
}

function draw() {
  background(220);

